    [Parameter, EditorRequired]
    public RenderFragment<TItem> ChildContent { get; set; } = default!;

    private ElementReference sentinelRef;
    private IJSObjectReference? moduleRef;
    private DotNetObjectReference<InfiniteScrollList<TItem>>? dotNetRef;
    private bool isLoading;

    protected override async Task OnAfterRenderAsync(bool firstRender)
    {
        if (firstRender)
        {
            dotNetRef = DotNetObjectReference.Create(this);
            moduleRef = await JS.InvokeAsync<IJSObjectReference>(
                "import", "./_content/sv-46b2a2a699ea43ee9115f721b51c4fd2/infinite-scroll.js");
            await moduleRef.InvokeVoidAsync("observe", sentinelRef, dotNetRef);
        }
    }

    [JSInvokable]
    public async Task OnIntersecting()
    {
        if (isLoading || !HasMore)
            return;

        isLoading = true;
        StateHasChanged();

        await OnLoadMore.InvokeAsync();

        isLoading = false;
        StateHasChanged();
    }

    public async ValueTask DisposeAsync()
    {
        if (moduleRef is not null)
        {
            await moduleRef.InvokeVoidAsync("disconnect");
            await moduleRef.DisposeAsync();
        }
        dotNetRef?.Dispose();
    }
}

using Microsoft.AspNetCore.Components;
using Microsoft.JSInterop;

namespace sv_46b2a2a699ea43ee9115f721b51c4fd2.Components;

public partial class InfiniteScrollList<TItem> : IAsyncDisposable
{
    [Inject]
    private IJSRuntime JS { get; set; } = default!;
}

.infinite-scroll-container {
    overflow-y: auto;
    max-height: 100%;
}

.infinite-scroll-sentinel {
    display: flex;
    justify-content: center;
    padding: 1rem;
    min-height: 1px;
}

.infinite-scroll-spinner {
    width: 2rem;
    height: 2rem;
    border: 3px solid #e0e0e0;
    border-top-color: #3b82f6;
    border-radius: 50%;
    animation: spin 0.8s linear infinite;
}

@keyframes spin {
    to {
        transform: rotate(360deg);
    }
}

let observer = null;

export function observe(sentinel, dotNetRef) {
    disconnect();

    observer = new IntersectionObserver((entries) => {
        for (const entry of entries) {
            if (entry.isIntersecting) {
                dotNetRef.invokeMethodAsync('OnIntersecting');
            }
        }
    }, {
        rootMargin: '0px 0px 200px 0px'
    });

    observer.observe(sentinel);
}

export function disconnect() {
    if (observer) {
        observer.disconnect();
        observer = null;
    }
}

